package com.bankease.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="users",indexes=@Index(name="idx_users_email",columnList="email",unique=true)) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=120) private String email; @Column(nullable=false) private String password; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Role role; @Column(nullable=false) private boolean enabled=true; @Column(nullable=false,updatable=false) private LocalDateTime createdAt; @PrePersist void prePersist(){createdAt=LocalDateTime.now();} }